package install

import (
	"crypto/ed25519"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"time"
)

type CatalogTrust interface{VerifyCatalog(SignedCatalog,time.Time)(Catalog,error)}
type TrustedKey struct{ID string;PublicKey ed25519.PublicKey;NotBefore time.Time;NotAfter time.Time;MinimumSequence uint64}
type KeyRing struct{Keys map[string]TrustedKey}
func (ring KeyRing) VerifyCatalog(signed SignedCatalog,now time.Time)(Catalog,error){key,ok:=ring.Keys[signed.KeyID];if !ok||len(key.PublicKey)!=ed25519.PublicKeySize||now.Before(key.NotBefore)||!now.Before(key.NotAfter)||signed.Payload.Sequence<key.MinimumSequence{return Catalog{},ErrIntegrity};payload,err:=json.Marshal(signed.Payload);if err!=nil{return Catalog{},err};signature,err:=base64.RawStdEncoding.DecodeString(signed.Signature);if err!=nil{signature,err=base64.StdEncoding.DecodeString(signed.Signature)};if err!=nil||len(signature)!=ed25519.SignatureSize||!ed25519.Verify(key.PublicKey,payload,signature){return Catalog{},ErrIntegrity};if err:=signed.Payload.Validate(now);err!=nil{return Catalog{},err};return signed.Payload,nil}

type keyDocument struct{ID string `json:"id"`;PublicKey string `json:"public_key"`;NotBefore time.Time `json:"not_before"`;NotAfter time.Time `json:"not_after"`;MinimumSequence uint64 `json:"minimum_sequence"`}
func LoadRootOwnedKeyRing(directory string,now time.Time)(KeyRing,error){if directory!="/etc/cyberpanel/installer/trust.d"{return KeyRing{},ErrIntegrity};info,err:=os.Stat(directory);if err!=nil{return KeyRing{},err};if err:=requireRootOwned(info,0755);err!=nil{return KeyRing{},err};entries,err:=os.ReadDir(directory);if err!=nil{return KeyRing{},err};ring:=KeyRing{Keys:map[string]TrustedKey{}};for _,entry:=range entries{if entry.IsDir()||entry.Type()&os.ModeSymlink!=0||filepath.Ext(entry.Name())!=".json"{continue};path:=filepath.Join(directory,entry.Name());info,err:=entry.Info();if err!=nil{return KeyRing{},err};if err:=requireRootOwned(info,0644);err!=nil{return KeyRing{},err};payload,err:=os.ReadFile(path);if err!=nil{return KeyRing{},err};var document keyDocument;if json.Unmarshal(payload,&document)!=nil||!safeID.MatchString(document.ID)||document.MinimumSequence==0||document.NotBefore.IsZero()||!document.NotAfter.After(document.NotBefore){return KeyRing{},ErrIntegrity};raw,err:=hex.DecodeString(document.PublicKey);if err!=nil||len(raw)!=ed25519.PublicKeySize{return KeyRing{},ErrIntegrity};if _,exists:=ring.Keys[document.ID];exists{return KeyRing{},ErrConflict};ring.Keys[document.ID]=TrustedKey{ID:document.ID,PublicKey:ed25519.PublicKey(raw),NotBefore:document.NotBefore,NotAfter:document.NotAfter,MinimumSequence:document.MinimumSequence}};if len(ring.Keys)==0{return KeyRing{},ErrNotFound};return ring,nil}
func requireRootOwned(info os.FileInfo,maximum os.FileMode)error{stat,ok:=info.Sys().(*syscall.Stat_t);if !ok||stat.Uid!=0||info.Mode().Perm()&^maximum!=0||info.Mode().Perm()&0022!=0{return ErrIntegrity};return nil}
func LoadCatalog(path string,trust CatalogTrust,now time.Time)(Catalog,error){if trust==nil||!filepath.IsAbs(path){return Catalog{},ErrInvalid};payload,err:=os.ReadFile(path);if err!=nil{return Catalog{},err};if len(payload)>32<<20{return Catalog{},ErrInvalid};var signed SignedCatalog;if json.Unmarshal(payload,&signed)!=nil||!safeID.MatchString(signed.KeyID)||signed.Signature==""{return Catalog{},ErrIntegrity};return trust.VerifyCatalog(signed,now)}

type CompileRequest struct{ID string;CommandID string;Kind TransactionKind;Tuple PlatformTuple;RequestDigest string;Catalog Catalog;Installed *InstalledState;TargetReleaseID string;EnterpriseLicense *EnterpriseLicenseRef;Now time.Time}
func CompilePlan(request CompileRequest)(TransactionPlan,TupleCatalog,error){if !safeID.MatchString(request.ID)||!safeID.MatchString(request.CommandID)||!validDigest(request.RequestDigest)||request.Now.IsZero(){return TransactionPlan{},TupleCatalog{},ErrInvalid};if request.Tuple.Edition==EditionLiteSpeedEnterprise&&(request.Kind==TransactionInstall||request.Kind==TransactionUpgrade){if request.EnterpriseLicense==nil||request.EnterpriseLicense.Validate()!=nil{return TransactionPlan{},TupleCatalog{},ErrInvalid}};tupleCatalog,err:=request.Catalog.For(request.Tuple);if err!=nil{return TransactionPlan{},TupleCatalog{},err};catalogDigest,err:=canonicalDigest(request.Catalog);if err!=nil{return TransactionPlan{},TupleCatalog{},err};plan:=TransactionPlan{ID:request.ID,CommandID:request.CommandID,Kind:request.Kind,Tuple:request.Tuple,RequestDigest:request.RequestDigest,CatalogID:request.Catalog.CatalogID,CatalogSequence:request.Catalog.Sequence,CatalogDigest:catalogDigest,TargetReleaseID:request.TargetReleaseID,State:TxAdmitted,Generation:1,CreatedAt:request.Now,UpdatedAt:request.Now};switch request.Kind{case TransactionInstall:if request.Installed!=nil{return TransactionPlan{},TupleCatalog{},ErrConflict};plan.TargetSlot=SlotA;case TransactionUpgrade:if request.Installed==nil||request.Catalog.Sequence<=request.Installed.CatalogSequence{return TransactionPlan{},TupleCatalog{},ErrConflict};plan.FromReleaseID=request.Installed.ReleaseID;plan.ActiveSlot=request.Installed.ActiveSlot;plan.TargetSlot=request.Installed.ActiveSlot.Other();case TransactionRollback:if request.Installed==nil||request.Installed.PreviousReleaseID==""||request.Installed.PreviousSlot==""{return TransactionPlan{},TupleCatalog{},ErrConflict};plan.FromReleaseID=request.Installed.ReleaseID;plan.TargetReleaseID=request.Installed.PreviousReleaseID;plan.ActiveSlot=request.Installed.ActiveSlot;plan.TargetSlot=request.Installed.PreviousSlot;case TransactionUninstall:if request.Installed==nil{return TransactionPlan{},TupleCatalog{},ErrNotFound};plan.FromReleaseID=request.Installed.ReleaseID;plan.ActiveSlot=request.Installed.ActiveSlot;default:return TransactionPlan{},TupleCatalog{},ErrInvalid};if plan.TargetReleaseID==""&&request.Kind!=TransactionUninstall{return TransactionPlan{},TupleCatalog{},ErrInvalid};components,err:=sortedComponents(tupleCatalog.Components);if err!=nil{return TransactionPlan{},TupleCatalog{},err};add:=func(kind StepKind,component ComponentID,input any)error{digest,err:=canonicalDigest(input);if err!=nil{return err};index:=uint32(len(plan.Steps));plan.Steps=append(plan.Steps,PlanStep{Index:index,ID:fmt.Sprintf("%03d-%s-%s",index,kind,component),Kind:kind,ComponentID:component,InputDigest:digest,State:"pending"});return nil};if request.Kind==TransactionUninstall{for _,entry:=range []struct{kind StepKind;input any}{{StepPreflight,request.Tuple},{StepExportState,request.RequestDigest},{StepDeactivate,request.Installed},{StepTombstone,request.RequestDigest}}{if err:=add(entry.kind,"",entry.input);err!=nil{return TransactionPlan{},TupleCatalog{},err}}}else if request.Kind==TransactionRollback{for _,entry:=range []struct{kind StepKind;input any}{{StepPreflight,request.Tuple},{StepArmWatchdog,request.Installed},{StepActivateSlot,plan.TargetSlot},{StepProbeServices,components},{StepDisarmWatchdog,plan.TargetSlot}}{if err:=add(entry.kind,"",entry.input);err!=nil{return TransactionPlan{},TupleCatalog{},err}}}else{if err:=add(StepPreflight,"",request.Tuple);err!=nil{return TransactionPlan{},TupleCatalog{},err};if err:=add(StepEnsureIdentity,"",[]IdentityID{IdentityPanel,IdentityGateway,IdentityAuthn,IdentitySecrets,IdentityContainers,IdentityWebAdmin});err!=nil{return TransactionPlan{},TupleCatalog{},err};for _,component:=range components{if len(component.Packages)>0{if err:=add(StepInstallPackages,component.ID,component.Packages);err!=nil{return TransactionPlan{},TupleCatalog{},err}};if component.Artifact!=nil{if err:=add(StepStageArtifact,component.ID,component.Artifact);err!=nil{return TransactionPlan{},TupleCatalog{},err};if err:=add(StepDeployArtifact,component.ID,component.Artifact.TreeDigest);err!=nil{return TransactionPlan{},TupleCatalog{},err}};if component.ID==ComponentWebEnterprise{if err:=add(StepInstallEnterpriseLicense,component.ID,request.EnterpriseLicense);err!=nil{return TransactionPlan{},TupleCatalog{},err}};if len(component.Files)>0{if err:=add(StepWriteFiles,component.ID,component.Files);err!=nil{return TransactionPlan{},TupleCatalog{},err}};if len(component.StateHooks)>0{if err:=add(StepInitializeState,component.ID,component.StateHooks);err!=nil{return TransactionPlan{},TupleCatalog{},err}};if len(component.Services)>0{if err:=add(StepEnableServices,component.ID,component.Services);err!=nil{return TransactionPlan{},TupleCatalog{},err}}};if request.Kind==TransactionUpgrade{if err:=add(StepArmWatchdog,"",plan.TargetSlot);err!=nil{return TransactionPlan{},TupleCatalog{},err}};if err:=add(StepActivateSlot,ComponentPanel,plan.TargetSlot);err!=nil{return TransactionPlan{},TupleCatalog{},err};if err:=add(StepProbeServices,"",components);err!=nil{return TransactionPlan{},TupleCatalog{},err};if request.Kind==TransactionUpgrade{if err:=add(StepDisarmWatchdog,"",plan.TargetSlot);err!=nil{return TransactionPlan{},TupleCatalog{},err}}};if err:=plan.Validate();err!=nil{return TransactionPlan{},TupleCatalog{},err};return plan,tupleCatalog,nil}

func ComponentMap(catalog TupleCatalog)map[ComponentID]ComponentDefinition{result:=make(map[ComponentID]ComponentDefinition,len(catalog.Components));for _,component:=range catalog.Components{result[component.ID]=component};return result}
func CatalogComponentVersions(catalog TupleCatalog)map[ComponentID]string{result:=map[ComponentID]string{};for _,component:=range catalog.Components{result[component.ID]=component.Version};return result}
func ReleaseVersion(catalog TupleCatalog)string{versions:=make([]string,0,len(catalog.Components));for _,component:=range catalog.Components{versions=append(versions,string(component.ID)+"="+component.Version)};sort.Strings(versions);return strings.Join(versions,",")}
func IsNotFound(err error)bool{return errors.Is(err,ErrNotFound)||errors.Is(err,os.ErrNotExist)}
